        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var ds = (last && last.domainState) || {};
            var mit = ds.mitsuyama || 0;
            var har = ds.hartmann || 0;
            var ara = ds.aramburu || 0;
            var fid = ds.culturalFidelity || 0;
            var protocol = ds.protocolScore || 0;
            var ceo = ds.ceoConfidence || 0;
            var avgProb = (mit + har + ara) / 3;
            // v1.2.0: tier and insights come from the en and es tables, so the debrief follows the language
            var t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };

            var perf = 'perf_beginner';
            if (avgProb > 60 && fid > 60 && protocol > 60) perf = 'perf_good';
            if (avgProb > 75 && fid > 75 && protocol > 75) perf = 'perf_excellent';

            var insights = [];
            if (mit < 40) insights.push(t('insight_japan_slipped'));
            if (har < 60) insights.push(t('insight_germany_drifted'));
            if (ara < 50) insights.push(t('insight_brazil_cooled'));
            if (fid < 50) insights.push(t('insight_low_fidelity'));
            if (protocol < 60) insights.push(t('insight_thin_protocol'));
            if (avgProb > 70 && fid > 70 && protocol > 70) insights.push(t('insight_strong_design'));
            if (ceo > 70 && protocol > 70) insights.push(t('insight_board_ready'));

            return {
                mitsuyama: mit,
                hartmann: har,
                aramburu: ara,
                avgProbability: avgProb,
                culturalFidelity: fid,
                protocolScore: protocol,
                ceoConfidence: ceo,
                performance: t(perf),
                insights: insights
            };
        }

        getHint(state, results) {
            var ds = state.domainState;
            if (ds.mitsuyama < 25) return window.mySimulation.t('hint_japan_lost');
