        _updateBriefing(state) {
            var period = (state && state.currentPeriod) || 1;
            if (period > 9) period = 9;
            if (period < 1) period = 1;
            var t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };

            var phaseEl = document.getElementById('phaseLabel');
            var partyEl = document.getElementById('counterpartyLabel');
            var titleEl = document.getElementById('scenarioTitle');
            var brEl    = document.getElementById('briefingText');
            var sel     = document.getElementById('choiceSelect');

            var phaseKey = period <= 3 ? 'phase_diagnose' : (period <= 6 ? 'phase_design' : 'phase_defend');
            var partyKeys = ['mitsuyama', 'hartmann', 'aramburu', 'mitsuyama', 'hartmann', 'aramburu', 'meta_ceo', 'meta_cfo', 'meta_gm'];
            var partyKey = 'party_' + partyKeys[period - 1];

            if (phaseEl) phaseEl.textContent = t(phaseKey);
            if (partyEl) partyEl.textContent = t(partyKey);
            if (titleEl) titleEl.textContent = t('p' + period + '_title');
            if (brEl)    brEl.innerHTML = t('p' + period + '_brief');

            if (sel) {
                var current = sel.value;
                sel.innerHTML = '';
                // v1.2.0: each round builds its options in its own order, and the EQIL guard keys its shuffle
                // on that order, so each round gets its own shuffle. With one order for every round the
                // shuffle was the same all game long and the rewarded option sat in the same place in most
                // rounds. Unshuffled, the rewarded option is first in rounds 1, 5 and 7, second in 2, 6
                // and 9, last in 3, 4 and 8. The values a, b and c and their scoring are unchanged. The option
                // texts no longer open with the letters A, B and C: shuffled, the letters came out of order,
                // and always taking B (the rewarded value in seven rounds) was a shortcut of its own.
                var ORDER = ['bca', 'cba', 'bac', 'acb', 'bac', 'abc', 'cab', 'cab', 'abc'];
                ORDER[period - 1].split('').forEach(function(opt) {
                    var o = document.createElement('option');
                    o.value = opt;
                    o.textContent = t('p' + period + '_' + opt);
                    sel.appendChild(o);
                });
                sel.value = current && ['a','b','c'].indexOf(current) >= 0 ? current : 'b';
            }
        }

